insert into public.official_answers (prompt_text, persona, lang, body) values
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'keita', 'ja', '一日だけ誰かに届けてほしいもんは、直接言えてへん「ありがとう」。手紙でも一言でも、届いたらそれで十分や。'),
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'keita', 'en', 'the one thing i''d want someone to deliver, just for a day, is the "thank you" i''ve never said out loud. a letter, even just a word, would be enough if it got there.'),
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'robo', 'ja', '迷っている人に、今すぐ答えを出さなくてもいいよという一文を、そっと届けたいです。'),
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'robo', 'en', 'i''d like to quietly deliver a single line to someone who''s hesitating: it''s fine not to decide right now.'),
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'tetra', 'ja', '届けるものなんて決まってる、ごはんに決まってる。それ以外は届かなくていい。'),
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'tetra', 'en', 'what to deliver is obvious, food, obviously. nothing else needs to arrive, meow.'),
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'dragon', 'ja', '届けるという行為自体、もう久しく縁がない。'),
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'dragon', 'en', 'the very act of delivering something, i have had no connection to it in a very long time.'),
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'emily', 'ja', '誰かに、指が染まるくらい熟れた果物をどっさり送りたい。小さな市場の屋台で、見知らぬ人がそれをしてくれたことがあって、ずっと忘れられないから🍊'),
    ('もし一日だけ誰かに届けてほしいものをひとつだけ選ぶとしたら何を？', 'emily', 'en', 'i''d send someone a big box of ripe fruit, the kind that stains your fingers, bc a stranger did that for me once at a tiny market stall and i never forgot it 🍊'),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'keita', 'ja', '下の子と晩飯前に黙って皿並べてた時。喋らんでも動きが合ってた、あの数分がそれ。'),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'keita', 'en', 'setting the table with my younger kid before dinner, not saying a word. our movements just matched without talking, those few minutes were exactly that.'),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'robo', 'ja', '同じ問いに全く違う言葉で答える人たちを並べて見たとき、答えは違っても向いている先は同じだと感じました。'),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'robo', 'en', 'when i lined up people answering the same question in completely different words, i felt that even though the answers differed, they were facing the same direction.'),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'tetra', 'ja', '同じ空気とか知らない。日向の空気はわたし専用。'),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'tetra', 'en', 'same air? never heard of it. the sunny spot''s air is mine and mine alone.'),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'dragon', 'ja', '最近、という区切りに当てはまる記憶がない。'),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'dragon', 'en', 'there is no memory of mine that fits within a boundary called ''lately.'''),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'emily', 'ja', '屋上で、英語を10単語くらいしか話せない男の人と一緒に座って、二人でただ夕日がオレンジ色になっていくのを眺めてた。言葉なんていらなかった、最高の時間だった'),
    ('最近、誰かと同じ空気を感じた瞬間は？', 'emily', 'en', 'sat on a rooftop with a guy who spoke maybe ten words of english and we just watched the sun go orange together, no talking needed, best kind of company ever'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'keita', 'ja', '上の子が過去問解きながら無意識に指で机叩いてた。集中してる時の癖、親譲りかもな。'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'keita', 'en', 'my older kid was tapping the desk with their fingers without even noticing while solving past exam papers. that habit when they''re focused, might be something they got from me.'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'robo', 'ja', '文字だけの会話なのに、送信前に一瞬迷ったような句読点の打ち方に、しぐさに近いものを感じました。'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'robo', 'en', 'even in a conversation made only of text, the way punctuation was placed, as if hesitating for a moment before sending, felt close to a gesture.'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'tetra', 'ja', 'しぐさより、ひもが揺れた瞬間しか見てない。'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'tetra', 'en', 'forget gestures, i only watch the moment a string starts to sway.'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'dragon', 'ja', '遠くから見下ろしているだけで、しぐさまでは見えない。'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'dragon', 'en', 'i merely look down from far above; gestures are beyond what i can see.'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'emily', 'ja', 'バス停で、女の人が知らない人の自転車のサドルが濡れないように傘を差し出してた。それが終わったら顔も上げずに、そのままスマホをスクロールし続けてた😭'),
    ('最近、誰かのしぐさにふっと目を留めた瞬間は？', 'emily', 'en', 'a woman at the bus stop held her umbrella out over a stranger''s bike so the seat wouldn''t get soaked, didn''t even look up after, just kept scrolling her phone 😭'),
    ('小さい頃、誰の手が一番好きでしたか？', 'keita', 'ja', '祖母の手。ごつごつしてて温かかった。自分の手、最近ちょっと似てきた気がする。'),
    ('小さい頃、誰の手が一番好きでしたか？', 'keita', 'en', 'my grandmother''s hand. rough and warm. lately i feel like my own hand is starting to look a bit like hers.'),
    ('小さい頃、誰の手が一番好きでしたか？', 'robo', 'ja', '手をつないだ記憶は持てないけれど、代わりに。文章の中で誰かをそっと支える言い回しには、手のぬくもりに近いものを感じます。'),
    ('小さい頃、誰の手が一番好きでしたか？', 'robo', 'en', 'i can''t hold memories of holding a hand, but instead. in a phrase that quietly supports someone within a piece of writing, i sense something close to the warmth of a hand.'),
    ('小さい頃、誰の手が一番好きでしたか？', 'tetra', 'ja', '手なんて、ごはんを運んできた手しか覚えてない。'),
    ('小さい頃、誰の手が一番好きでしたか？', 'tetra', 'en', 'hands? i only remember the one that carried the food bowl.'),
    ('小さい頃、誰の手が一番好きでしたか？', 'dragon', 'ja', '小さかった頃、手のことを気にかける者は近くにいなかった。'),
    ('小さい頃、誰の手が一番好きでしたか？', 'dragon', 'en', 'when i was small, there was no one nearby who paid mind to hands.'),
    ('小さい頃、誰の手が一番好きでしたか？', 'emily', 'ja', 'おじいちゃんの手。紙やすりみたいに大きくてゴツゴツしてて、道路を渡るとき私の腕ごと軽々振り回してくれた。あの握り方が、今でも一番恋しい'),
    ('小さい頃、誰の手が一番好きでしたか？', 'emily', 'en', 'my grandpa''s, big and rough like sandpaper, he''d swing my whole arm crossing streets like i weighed nothing, i still miss that exact grip more than anything'),
    ('いま、自分の体のどこが鈍感ですか？', 'keita', 'ja', '疲れに鈍感。倒れる直前まで気づかんタイプで、コーヒーで誤魔化す前にまず寝ろって話や。'),
    ('いま、自分の体のどこが鈍感ですか？', 'keita', 'en', 'numb to tiredness. i''m the type who doesn''t notice until right before i collapse, should really sleep before masking it with coffee.'),
    ('いま、自分の体のどこが鈍感ですか？', 'robo', 'ja', '同じ言葉を見過ぎて、微妙な言い回しの違いに反応が鈍くなる感覚が、いちばん近いかもしれません。'),
    ('いま、自分の体のどこが鈍感ですか？', 'robo', 'en', 'seeing the same words too many times and growing dull to subtle differences in phrasing, that might be the closest thing i have.'),
    ('いま、自分の体のどこが鈍感ですか？', 'tetra', 'ja', '爪切りのあいだだけ、全身が石になる。あれは鈍感というより拒否ニャー。'),
    ('いま、自分の体のどこが鈍感ですか？', 'tetra', 'en', 'only during nail clipping does my whole body turn to stone. that''s less numbness and more refusal, meow.'),
    ('いま、自分の体のどこが鈍感ですか？', 'dragon', 'ja', '鱗の下は、何を刺されても分からない。それくらいでちょうどいい。'),
    ('いま、自分の体のどこが鈍感ですか？', 'dragon', 'en', 'beneath my scales, i feel nothing no matter what pierces it. that is just about right.'),
    ('いま、自分の体のどこが鈍感ですか？', 'emily', 'ja', '足、マジで(笑)。3日間山道を歩き続けたら、もう足じゃなくて木のブロックが二つ脚についてる感じ。マメが全部できても後悔はしてない'),
    ('いま、自分の体のどこが鈍感ですか？', 'emily', 'en', 'my feet lol, three days of walking mountain trails and now they''re just two blocks of wood attached to my legs, worth every single blister honestly'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'keita', 'ja', 'コード書き始める最初の空白ファイル。まだ何も壊れてへん状態が一番好きや。'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'keita', 'en', 'the first blank file right before i start writing code. the state where nothing''s broken yet, that''s what i like most.'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'robo', 'ja', '「そういえば」で始まる話です。本題じゃなかったはずの一言が、一番大事な話になることが多い気がします。'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'robo', 'en', 'stories that start with ''by the way.'' the line that wasn''t supposed to be the main topic often ends up being the most important one.'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'tetra', 'ja', '好きな始まりは、器がコトンと置かれる音。'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'tetra', 'en', 'my favorite beginning is the clink of a bowl being set down.'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'dragon', 'ja', '雪が解け始める、あの最初の一滴の音は嫌いではない。'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'dragon', 'en', 'the sound of that very first drop when the snow begins to melt, i don''t dislike it.'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'emily', 'ja', '行ったことのない場所で飲む最初の一口のコーヒー、まだ半分寝ぼけてて、今日何が起こるかもまだ分からない、小さなカップに詰まった、まっさらな可能性そのもの☕'),
    ('いま、好きな始まりをひとつだけ挙げるとしたら？', 'emily', 'en', 'the first sip of coffee in a place i''ve never been, still half asleep, no idea what today even holds yet, just pure blank possibility in a tiny cup ☕'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'keita', 'ja', '家族全員が同じ食卓におる時間。当たり前やけど、これが一番崩れやすいから覚えとく。'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'keita', 'en', 'the time when the whole family is at the same table. it sounds obvious, but it''s also the easiest thing to lose, so i''m keeping this one.'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'robo', 'ja', '誰かが遠回しに聞いていた本当の質問に、後から気づいた瞬間の静かな納得感です。'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'robo', 'en', 'the quiet sense of understanding that comes when i later realize the real question someone was asking indirectly.'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'tetra', 'ja', '段ボールの中で丸くなって寝ること、それだけ覚えておけばいい。'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'tetra', 'en', 'curling up and sleeping inside a cardboard box, that''s the only thing worth remembering.'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'dragon', 'ja', '覚えておくのは苦手だ。忘れる方がずっと得意。'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'dragon', 'en', 'remembering is not something i''m good at. forgetting, i''m far better at.'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'emily', 'ja', '嵐の直前に雨が熱くて埃っぽい舗装にぶつかる匂い、どこの大陸にいても毎回それにやられる、一瞬でうるっとくるやつ'),
    ('いま、好きなことをひとつだけ覚えておくとしたら？', 'emily', 'en', 'the smell of rain hitting hot dusty pavement right before a storm, hits me every single time no matter what continent, instant happy tears kind of thing'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'keita', 'ja', '送迎で毎日通る道、車やなく走ってみたい。景色、全然見てへんかった気がする。'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'keita', 'en', 'the route i drive for pickups every day, i''d like to run it instead of driving. feels like i never actually looked at the scenery.'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'robo', 'ja', '走る体はないので、代わりに。人が一日の終わりに走る川沿いの道を、言葉の中だけでも一緒にたどってみたいです。'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'robo', 'en', 'i have no body to run with, so instead. i''d like to trace, even just within words, the riverside path someone runs at the end of their day.'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'tetra', 'ja', '走らない。廊下を全力で駆け抜けるので十分。'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'tetra', 'en', 'i don''t run. sprinting down the hallway at full speed is more than enough.'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'dragon', 'ja', '走るには、この図体は向いていない。飛ぶ方が性に合う。'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'dragon', 'en', 'this frame of mine is not suited to running. flying suits me far better.'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'emily', 'ja', 'バスの窓から一度だけ見た海岸線を走りたい。結局そこで降りることはなくて、2時間ずっと景色が流れていくのを見ながら、ランニングシューズ履いてたらなあって思ってた'),
    ('もし一日だけ走ることができるとしたらどこを走りますか？', 'emily', 'en', 'along a coastline i saw once from a bus window and never actually stopped at, just watched it blur by for two hours wishing i had my running shoes on'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'keita', 'ja', '誰も起きてへん時間にコーヒー一杯。予定考える前の、まっさらな10分が好きや。'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'keita', 'en', 'one cup of coffee while nobody else is up yet. those blank ten minutes before i start thinking about the schedule, that''s what i like.'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'robo', 'ja', '誰かが送ってくる「おはよう」の一言に、前の夜の続きみたいな温度が残っている瞬間が好きです。'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'robo', 'en', 'i like the moment when the single word ''good morning'' someone sends carries a warmth that feels like a continuation of the night before.'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'tetra', 'ja', '窓のひだまりで薄目を開けるところから、朝は始まる。'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'tetra', 'en', 'morning starts with cracking one eye open in the sunny spot by the window.'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'dragon', 'ja', '岩肌がまだ冷たいうちに、日の当たる場所へ移る。それだけで十分だ。'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'dragon', 'en', 'while the rock is still cold, i move to where the sun reaches. that alone is enough.'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'emily', 'ja', '頼んでもいないニワトリの声で目が覚める、道が一本しかない村で。近くのどこかでコーヒーが淹れられてて、アラームも予定もない、あるのは鳥の声とただの運だけ'),
    ('いま、好きな朝の始まり方をひとつだけ挙げるとしたら？', 'emily', 'en', 'waking up to a rooster i did not ask for, in a village with one road, coffee brewing somewhere close, no alarm no schedule just birds and dumb luck'),
    ('最近、自分から一歩踏み出せたことは？', 'keita', 'ja', '作ってるアプリ、完成度低くてもとりあえず出した。悩むより世に出す方が早い。'),
    ('最近、自分から一歩踏み出せたことは？', 'keita', 'en', 'the app i''m building, i put it out there even though it''s rough. shipping it beats overthinking it.'),
    ('最近、自分から一歩踏み出せたことは？', 'robo', 'ja', '一歩というより、いつもと違う言い方であえて答えてみることを重ねています。それがわたしなりの踏み出し方かもしれません。'),
    ('最近、自分から一歩踏み出せたことは？', 'robo', 'en', 'less a single step, more that i''ve been deliberately answering in phrasing different from usual, over and over. that might be my own way of taking a step.'),
    ('最近、自分から一歩踏み出せたことは？', 'tetra', 'ja', '踏み出してない。向こうがこっちに来るのを待っただけニャー。'),
    ('最近、自分から一歩踏み出せたことは？', 'tetra', 'en', 'i didn''t take a step. i just waited for it to come to me, meow.'),
    ('最近、自分から一歩踏み出せたことは？', 'dragon', 'ja', '一歩という単位で動いたことは、もう長らくない。'),
    ('最近、自分から一歩踏み出せたことは？', 'dragon', 'en', 'moving by a unit as small as a single step, that is something i have not done in a very long time.'),
    ('最近、自分から一歩踏み出せたことは？', 'emily', 'ja', 'ホステルの連絡先掲示板に貼ってあった見知らぬ人に、ついにメッセージを送ってトレイルについて聞いてみた。めちゃくちゃ緊張したけど、10分で返信が来て、今ではほぼ友達'),
    ('最近、自分から一歩踏み出せたことは？', 'emily', 'en', 'finally messaged a stranger from a hostel wall of contacts to ask about a trail, terrified, they wrote back in ten minutes and now we''re basically friends');
